void StepSequencerComponent::highlightRows(const std::vector<int>& rowIndices)
{
    // Initialize highlight alphas if needed
    if (rowHighlightAlpha_.size() != grid_.size()) {
        rowHighlightAlpha_.resize(grid_.size(), 0.0f);
    }
    // Set highlight for specified rows
    for (int row : rowIndices) {
        if (row >= 0 && row < (int)rowHighlightAlpha_.size()) {
            rowHighlightAlpha_[row] = 1.0f;
        }
    }
    repaint();
}
